   cur=self.ikd.site_xpos[self.site]; cr=self.ikd.site_xmat[self.site].reshape(3,3)
   err=np.r_[p-cur,Rotation.from_matrix(R@cr.T).as_rotvec()*.6]
   if np.linalg.norm(err)<.0001:break
